struct Collection {
    string type;
    vector<int> items;   // used when type == "array"
    Node* head;           // used when type == "linkedList"
};

void printAll(const Collection& collection) {
    if (collection.type == "array") {
        for (size_t i = 0; i < collection.items.size(); i++) {
            cout << collection.items[i] << endl;
        }
    } else if (collection.type == "linkedList") {
        Node* node = collection.head;
        while (node != nullptr) {
            cout << node->value << endl;
            node = node->next;
        }
    } else if (collection.type == "tree") {
        // yet another traversal, written inline here
    }
}

