class Iterator {
public:
    virtual bool hasNext() = 0;
    virtual string next() = 0;
    virtual ~Iterator() = default;
};

class PlaylistIterator : public Iterator {
private:
    vector<string> songs;
    int position = 0;

public:
    PlaylistIterator(vector<string> songs) : songs(songs) {}

    bool hasNext() override {
        return position < (int)songs.size();
    }

    string next() override {
        string song = songs[position];
        position += 1;
        return song;
    }
};

