class BSTIterator {
private:
    stack<Node*> nodeStack;

    void pushLeft(Node* node) {
        while (node != nullptr) {
            nodeStack.push(node);
            node = node->left;
        }
    }

public:
    BSTIterator(Node* root) {
        pushLeft(root);
    }

    bool hasNext() {
        return !nodeStack.empty();
    }

    int next() {
        Node* node = nodeStack.top();
        nodeStack.pop();
        if (node->right != nullptr) {
            pushLeft(node->right);
        }
        return node->value;
    }
};

